/**
 * PLACEHOLDER — NOT PART OF THE DESIGN.
 *
 * Better Auth tables are generated by the Better Auth CLI (decision 3) and must not be hand-designed.
 * This file exists only so the schema drafts type-check and the RLS tests can run: it declares the
 * columns our tables reference (`user.id`, `organization.id`) plus the `member` columns the policy
 * layer reads. Replace it with the CLI output (`npx @better-auth/cli generate`) — verify in docs —
 * and keep the import names (`user`, `organization`, `member`) the same.
 */
import { pgTable, text, timestamp } from "drizzle-orm/pg-core";

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const organization = pgTable("organization", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const member = pgTable("member", {
  id: text("id").primaryKey(),
  organizationId: text("organization_id").notNull().references(() => organization.id),
  userId: text("user_id").notNull().references(() => user.id),
  role: text("role").notNull(), // "owner" | "member"
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});
